import{_ as t,o,c as d,ae as c}from"./chunks/framework.Dwq5SdLE.js";const h=JSON.parse('{"title":"scriptSetup 代码片段","description":"","frontmatter":{},"headers":[],"relativePath":"script-setup.md","filePath":"script-setup.md"}'),a={name:"script-setup.md"};function r(s,e,n,i,l,p){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="scriptsetup-代码片段" tabindex="-1">scriptSetup 代码片段 <a class="header-anchor" href="#scriptsetup-代码片段" aria-label="Permalink to &quot;scriptSetup 代码片段&quot;">​</a></h1><p><code>scriptSetup</code> 是字符串数组，每个元素是一段独立的 JS 代码片段，运行时按数组顺序拼接注入到动态构造的 setup 函数体内。因此：</p><ul><li><strong>片段存在顺序依赖</strong>：后段可以引用前段声明的变量，反之不行（不做声明提升分析）；</li><li><strong>与模板共享同一作用域</strong>：片段中声明的 <code>ref</code>、handler 等可被 <code>template</code> 中的表达式与事件直接引用，语义与 <code>&lt;script setup&gt;</code> 一致；</li><li>建议一个片段聚焦一件事（数据声明、事件处理、局部组件定义等），便于来源管理与排查。</li></ul><h2 id="可直接使用的注入变量" tabindex="-1">可直接使用的注入变量 <a class="header-anchor" href="#可直接使用的注入变量" aria-label="Permalink to &quot;可直接使用的注入变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>可用标识符</th></tr></thead><tbody><tr><td>组件与渲染</td><td><code>defineComponent</code>、<code>h</code>、<code>withDirectives</code>、<code>vShow</code>、<code>mergeProps</code>、<code>resolveDynamicComponent</code>、<code>resolveComponent</code></td></tr><tr><td>响应式</td><td><code>ref</code>、<code>shallowRef</code>、<code>reactive</code>、<code>computed</code>、<code>watch</code>、<code>watchEffect</code>、<code>toRef</code>、<code>toRefs</code>、<code>toRaw</code></td></tr><tr><td>生命周期</td><td><code>onMounted</code>、<code>onUnmounted</code>、<code>onBeforeMount</code>、<code>onBeforeUnmount</code></td></tr><tr><td>其他 API</td><td><code>getCurrentInstance</code>、<code>nextTick</code>、<code>provide</code>、<code>inject</code></td></tr><tr><td>内置上下文</td><td><code>props</code>、<code>emit</code>、<code>slots</code>、<code>attrs</code>、<code>expose</code>（setup 参数解构）；<code>router</code>、<code>route</code>（vue-router 已注册时注入，未注册时为 <code>undefined</code> 占位）</td></tr></tbody></table><h2 id="内置辅助函数" tabindex="-1">内置辅助函数 <a class="header-anchor" href="#内置辅助函数" aria-label="Permalink to &quot;内置辅助函数&quot;">​</a></h2><p>无需声明即可使用，与业务代码同作用域：</p><table tabindex="0"><thead><tr><th>函数</th><th>职责</th></tr></thead><tbody><tr><td><code>resolveEepress(fn)</code></td><td>表达式求值容错：执行 thunk，异常时返回 <code>undefined</code>，保证单个表达式错误不打断整页渲染</td></tr><tr><td><code>resolveEepressSet(setter)</code></td><td>表达式赋值容错（v-model 写入端）</td></tr><tr><td><code>withVfor(keyField, arrayFn, cb)</code></td><td>循环渲染容错：数据源非数组或求值失败时安全返回 <code>undefined</code>，正常时 map 生成节点数组并按 keyField 取 key</td></tr></tbody></table><h2 id="保留字约束" tabindex="-1">保留字约束 <a class="header-anchor" href="#保留字约束" aria-label="Permalink to &quot;保留字约束&quot;">​</a></h2><p><code>scriptSetup</code> 中不要声明与上述注入变量同名的标识符（如 <code>const h = ...</code>），否则 <code>const</code> 重复声明会导致整个组件编译失败；引擎在开发态会对这类冲突输出 <code>console.warn</code> 预警。</p><h2 id="局部组件定义示例" tabindex="-1">局部组件定义示例 <a class="header-anchor" href="#局部组件定义示例" aria-label="Permalink to &quot;局部组件定义示例&quot;">​</a></h2><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;const MyPanel = defineComponent({ name: &#39;MyPanel&#39;, props: { title: String }, emits: [&#39;update:title&#39;], setup(panelProps, { emit, slots }) { return () =&gt; h(&#39;div&#39;, { class: &#39;panel&#39; }, [ h(&#39;div&#39;, null, slots.title ? slots.title() : panelProps.title), slots.default ? slots.default({ label: &#39;作用域数据&#39; }) : null ]) } })&quot;</span></span></code></pre></div><p>定义后，<code>template</code> 中即可通过 <code>&quot;type&quot;: &quot;MyPanel&quot;</code> 引用（type 取 setup 上下文变量）。</p>',13)])])}const m=t(a,[["render",r]]);export{h as __pageData,m as default};
